<script setup lang="ts">
import { computed, markRaw, onBeforeUnmount, onErrorCaptured, onMounted, ref, shallowRef, type Component } from 'vue'
import { plays, type Play } from './plays'
const selected = ref<Play>(); const sequence = ref(0)
function choose(play: Play) { selected.value = play; sequence.value++ }
const diagram = computed(() => selected.value?.points.map(([x,z]) => [280 + x * 52.4, 190 + z * 54.6]) ?? [])
const arrival=ref<'tunnel'|'pitch'>('pitch'); const skip=ref(0)
const paused = ref(false)
const host = ref<HTMLElement>(); const scene = shallowRef<Component>(); const reduced = ref(true); const visible = ref(false); const failed = ref(false)
let observer: IntersectionObserver | undefined; let media: MediaQueryList | undefined; let alive = true; let supported: boolean | undefined
const showScene = computed(() => visible.value && !reduced.value && !failed.value && !!scene.value)
async function loadScene() { if (reduced.value || !visible.value || failed.value || scene.value) return; if (supported === undefined) { try { const canvas = document.createElement('canvas'); const gl = canvas.getContext('webgl2'); supported = !!gl; gl?.getExtension('WEBGL_lose_context')?.loseContext() } catch { supported = false } } if (!supported) return; try { const module = await import('./PitchScene.vue'); if (alive) scene.value = markRaw(module.default) } catch { failed.value = true } }
function motionChanged() { reduced.value = media?.matches ?? true; void loadScene() }
function contextLost(event: Event) { event.preventDefault(); failed.value = true }
onErrorCaptured(() => { failed.value = true; return false })
onMounted(() => { media = window.matchMedia('(prefers-reduced-motion: reduce)'); reduced.value = media.matches; media.addEventListener('change', motionChanged); if ('IntersectionObserver' in window) { observer = new IntersectionObserver(entries => { visible.value = !!entries[0]?.isIntersecting; void loadScene() }); if (host.value) observer.observe(host.value) } else { visible.value = true; void loadScene() } })
onBeforeUnmount(() => { alive = false; observer?.disconnect(); media?.removeEventListener('change', motionChanged) })
</script>
<template><div ref="host" class="pitch-visual" data-testid="pitch-hero" :data-arrival="showScene ? arrival : 'static'" :data-render-mode="showScene ? '3d' : 'fallback'" :data-fallback-reason="showScene ? undefined : reduced ? 'reduced-motion' : failed ? 'render-error' : !visible ? 'offscreen' : 'webgl-unavailable'" role="group" aria-label="Interactive stadium. Hypothetical tactical demonstration, not live tracking." :data-renderer="showScene ? 'webgl' : 'static'" @webglcontextlost.capture="contextLost"><svg class="pitch-fallback" :class="{ 'scene-active': showScene }" viewBox="0 0 700 500" aria-hidden="true"><defs><linearGradient id="field-light" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#234a40" /><stop offset="1" stop-color="#112b30" /></linearGradient></defs><g transform="translate(100 130) skewY(-13) scale(.9 .65)"><rect x="-16" y="12" width="592" height="390" fill="#132c32" stroke="#62e0f0" stroke-width="3" /><rect x="-16" y="-12" width="592" height="400" fill="#243c41" stroke="#547075" /><rect width="560" height="380" fill="url(#field-light)" stroke="#477866" /><g fill="none" stroke="#bcff63" stroke-opacity=".65" stroke-width="2"><rect x="18" y="18" width="524" height="344" /><path d="M280 18V362M18 100H100V280H18M542 100H460V280H542M18 145H50V235H18M542 145H510V235H542" /><circle cx="280" cy="190" r="55" /><circle cx="280" cy="190" r="3" /></g><g v-if="diagram.length"><polyline :points="diagram.map(p => p.join(',')).join(' ')" fill="none" stroke="#62e0f0" stroke-width="5" stroke-dasharray="9 5" /><circle v-for="(point,index) in diagram" :key="index" :cx="point[0]" :cy="point[1]" :r="index === diagram.length - 1 ? 9 : 6" :fill="index === diagram.length - 1 ? '#f5fff5' : '#bcff63'" stroke="#0a1519" stroke-width="2" /></g></g></svg><component :is="scene" v-if="showScene" :paused="paused" :play="selected" :sequence="sequence" :skip="skip" @arrival="arrival=$event" @failed="failed = true" /><button v-if="showScene && arrival==='tunnel'" class="skip-arrival" @click="skip++">Skip stadium entrance</button><button v-if="showScene" class="motion-toggle" :aria-pressed="paused" @click="paused = !paused">{{ paused ? 'Resume motion' : 'Pause motion' }}</button><span class="pitch-coordinate" aria-hidden="true">105 × 68 / THE BEAUTIFUL GAME</span></div><div class="play-console"><div class="play-controls"><p class="eyebrow">TACTICAL DEMO · HYPOTHETICAL</p><div role="group" aria-label="Choose a tactical play"><button v-for="(play,index) in plays" :key="play.label" :aria-pressed="selected?.label === play.label" @click="choose(play)"><span aria-hidden="true">0{{ index + 1 }}</span> {{ play.label }}</button></div></div><p class="play-description" aria-live="polite">{{ selected?.description ?? 'Choose a play to see how the ball could move. Each selection illustrates a different football idea.' }}</p></div></template>
